<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
use App\Domain\Transfers\TransferRules;
final class TransfersController extends AdminController {
 private function allowed(int $actor,string $permission):?array {return AppKernel::access()->accessibleBranchIdsForPermission($actor,'transfers.'.$permission);}
 private function missing($user):Response {return $this->adminView('admin/error',['title'=>'Transferencia no disponible','message'=>'El documento no existe o está fuera de tu alcance.','user'=>$user],404);}
 public function index(Request $r):Response {$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'view');if($allowed===[])return $this->requirePermission($u,'transfers.view')??Response::redirect('/admin');
  return $this->adminView('admin/transfers/index',['title'=>'Transferencias','activeNav'=>'transfers','user'=>$u,'page'=>AppKernel::transfers()->listing($r->query('q'),$r->query('status'),$r->integer('branch_id')?:null,$allowed,max(0,(int)$r->query('offset','0'))),'q'=>$r->query('q'),'status'=>$r->query('status'),'branchId'=>$r->integer('branch_id'),'branches'=>array_filter(AppKernel::transfers()->branches(),fn($b)=>$allowed===null||in_array((int)$b['id'],$allowed,true)),'canCreate'=>$this->allowed($u->id,'create')!==[]]);
 }
 public function createForm(Request $r,array $values=[],?string $error=null):Response {$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'create');if($allowed===[])return $this->requirePermission($u,'transfers.create')??Response::redirect('/admin');
  return $this->adminView('admin/transfers/create',['title'=>'Solicitar transferencia','activeNav'=>'transfers','user'=>$u,'values'=>$values?:['operation_key'=>bin2hex(random_bytes(20)),'quote_version_id'=>$r->query('quote_version_id'),'destination_branch_id'=>$r->query('destination_branch_id')],'quoteOptions'=>AppKernel::transfers()->quoteOptions($allowed),'error'=>$error,'branches'=>AppKernel::transfers()->branches(),'destinations'=>array_filter(AppKernel::transfers()->branches(),fn($b)=>$allowed===null||in_array((int)$b['id'],$allowed,true)),'products'=>AppKernel::inventory()->variants($r->query('product_q'))],$error?422:200);
 }
 public function create(Request $r):Response {$u=$this->requireUser();if($u instanceof Response)return $u;if($e=$this->requireCsrf($r,$u))return $e;$allowed=$this->allowed($u->id,'create');if($allowed===[])return $this->requirePermission($u,'transfers.create')??Response::redirect('/admin');$input=[];foreach(['source_branch_id','destination_branch_id','quote_version_id','reason','operation_key']as $k)$input[$k]=$r->input($k);$items=[];$units=$r->keyedValues('unit_id');foreach($r->keyedValues('quantity')as $variant=>$qty)if(trim((string)$qty)!==''&&!preg_match('/^0(?:\.0+)?$/D',(string)$qty))$items[]=['variant_id'=>(string)$variant,'unit_id'=>$units[$variant]??'','quantity'=>$qty];
  try{$id=AppKernel::transferManagement()->create($input,$items,$allowed,$u->id,fn($id,$b,$a)=>AppKernel::audit()->record($u->id,'transfer.'.$a,'transfer',$id,$b,'success'));return Response::redirect('/admin/transfers/detail?id='.$id);}catch(\InvalidArgumentException|\App\Application\Exceptions\ApplicationException $e){$error=$e->getMessage();}catch(\Throwable){$error='No se pudo guardar. No se confirmaron cambios.';}$input['quantities']=$r->keyedValues('quantity');$input['units']=$r->keyedValues('unit_id');return $this->createForm($r,$input,$error);
 }
 public function products(Request $r):Response {$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'create');if($allowed===[])return $this->requirePermission($u,'transfers.create')??Response::redirect('/admin');$rows=[];foreach(AppKernel::inventory()->variants($r->query('q'))as $v){$v['balance']=$r->integer('source_branch_id')?AppKernel::inventory()->findBalance($r->integer('source_branch_id'),(int)$v['id']):null;$v['units']=AppKernel::inventory()->unitsForVariant((int)$v['id']);$rows[]=$v;}return new Response(json_encode($rows,JSON_THROW_ON_ERROR),200,['Content-Type'=>'application/json; charset=UTF-8','Cache-Control'=>'no-store']);}
 public function detail(Request $r):Response {$u=$this->requireUser();if($u instanceof Response)return $u;$allowed=$this->allowed($u->id,'view');if($allowed===[])return $this->requirePermission($u,'transfers.view')??Response::redirect('/admin');$t=AppKernel::transfers()->find($r->integer('id'),$allowed);if(!$t)return $this->missing($u);$actions=[];foreach(['edit','approve','prepare','dispatch','receive','cancel','incident']as $a){$b=(int)$t[in_array($a,['edit','receive','cancel'],true)?'destination_branch_id':'source_branch_id'];$actions[$a]=AppKernel::access()->hasPermission($u->id,'transfers.'.$a,$b);}$history=AppKernel::access()->hasPermission($u->id,'transfers.history',(int)$t['source_branch_id'])||AppKernel::access()->hasPermission($u->id,'transfers.history',(int)$t['destination_branch_id']);
  return $this->adminView('admin/transfers/detail',['title'=>$t['folio'],'activeNav'=>'transfers','user'=>$u,'transfer'=>$t,'items'=>AppKernel::transfers()->items((int)$t['id']),'history'=>$history?AppKernel::transfers()->history((int)$t['id']):[],'actions'=>$actions]);
 }
 public function action(Request $r):Response {$u=$this->requireUser();if($u instanceof Response)return $u;if($e=$this->requireCsrf($r,$u))return $e;$a=$r->input('action');if(!in_array($a,['edit','approve','prepare','dispatch','receive','cancel','incident'],true))return $this->missing($u);$allowed=$this->allowed($u->id,$a);if($allowed===[])return $this->requirePermission($u,'transfers.'.$a)??Response::redirect('/admin');$id=$r->integer('id');$t=AppKernel::transfers()->find($id);if(!$t)return $this->missing($u);$branch=(int)$t[in_array($a,['edit','receive','cancel'],true)?'destination_branch_id':'source_branch_id'];if($e=$this->requirePermission($u,'transfers.'.$a,$branch))return $e;
  return $this->run(fn()=>AppKernel::transferManagement()->action($id,(int)$r->input('lock_version'),$a,$r->keyedValues('quantity'),$r->input('operation_key'),$r->input('notes'),$allowed,$u->id,fn($id,$b,$action)=>AppKernel::audit()->record($u->id,'transfer.'.$action,'transfer',$id,$b,'success')),'Operación confirmada.','/admin/transfers/detail?id='.$id,$u->id,'transfer.'.$a,'transfer',$id,$branch);
 }
}
